 $clock=new class implements O\AssignmentOrderOriginalClock{public int $calls=0;public function nowUtc():string{$this->calls++;return '2026-09-02T09:00:00Z';}};
 return [$token,$clock,new O\AssignmentOrderOriginalProductionConfig($production,$f->prefix,$f->safeLog),$faults??new O\AssignmentOrderOriginalNoFaults()];
}
