function orphanFixed(callable $operation,bool $conflict=false):void {$caught=null;try{$operation();}catch(Throwable $e){$caught=$e;}$class=$conflict?O\AssignmentOrderOriginalPrivateOrphanFixtureConflict::class:O\AssignmentOrderOriginalPrivateOrphanFixtureUnavailable::class;assertSameValue($class,$caught===null?null:get_class($caught),'exact fixture exception');assertSameValue([substr($class,strrpos($class,'\\')+1),0,null],[$caught->getMessage(),$caught->getCode(),$caught->getPrevious()],'fixed exception shape');}
function orphanStorage($f):O\AssignmentOrderOriginalFileStorage{return new O\AssignmentOrderOriginalFileStorage($f->privateRoot,new O\AssignmentOrderOriginalFixedClock('2026-09-02T09:00:00Z'),new O\AssignmentOrderOriginalNoFaults());}
